99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
102	        HttpHeaders headers = new HttpHeaders();
103	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
104	        Collection<Owner> existingOwners = this.clinicService.findAllOwners();
105	        boolean telephoneTaken = existingOwners.stream()
106	            .anyMatch(existing -> existing.getTelephone().equals(owner.getTelephone()));
107	        if (telephoneTaken || HouseholdDuplicates.isRejectedDuplicate(owner, existingOwners, ownerFieldsDto.getSharesHousehold())) {
108	            return new ResponseEntity<>(HttpStatus.CONFLICT);
109	        }
110	        owner.setNamesakeCount(Namesakes.count(owner, existingOwners));
111	        HouseholdDuplicates.assignHousehold(owner, existingOwners, ownerFieldsDto.getSharesHousehold());
112	        String last = owner.getLastName();
113	        owner.setCustomerCode(last.substring(0, Math.min(3, last.length())).toUpperCase()
114	            + String.format("-%04d", existingOwners.size() + 1));
115	        this.clinicService.saveOwner(owner);
116	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
117	        headers.setLocation(UriComponentsBuilder.newInstance()
118	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
119	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
120	    }
