159	        owner.setId(ownerId);
160	        pet.setOwner(owner);
161	        pet.getType().setName(null);
162	        this.clinicService.savePet(pet);
163	        PetDto petDto = petMapper.toPetDto(pet);
164	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
